import { describe, expect, it } from "vitest";
import { z } from "zod";

import type { TableSchemas } from "./databaseDoc";
import { renderDatabaseDoc } from "./renderDatabaseDoc";
import type { DatabaseColumnRow, ForeignKeyRow, IndexRow, TableSqlRow } from "./rows";
import type { DatabaseDocInput } from "./typeSchemas";

const HEADER = [
  "# Database",
  "",
  "> Generated by `pnpm db:docs` from the migrations and `src/worker/db/tableSchemas.ts`. Do not edit it by hand.",
  ">",
  "> Descriptions come from the table schemas; columns, types, keys and indexes come from the migrated database.",
  ">",
  "> Required counts a primary key as required, as the app does; SQLite lets a non-INTEGER primary key hold NULL.",
  ">",
  "> Times are integer milliseconds since the Unix epoch (epoch ms).",
].join("\n");

function column(
  overrides: Partial<DatabaseColumnRow> & { name: string; tableName: string },
): DatabaseColumnRow {
  return { cid: 0, type: "TEXT", notNull: 1, defaultValue: null, primaryKey: 0, ...overrides };
}

function index(overrides: Partial<IndexRow> & { name: string; tableName: string }): IndexRow {
  return {
    unique: 0,
    origin: "c",
    partial: 0,
    sql: `CREATE INDEX ${overrides.name} ON ${overrides.tableName} (x)`,
    columns: ["x"],
    ...overrides,
  };
}

function tableSql(tableName: string, sql = `CREATE TABLE ${tableName} (id TEXT)`): TableSqlRow {
  return { tableName, sql };
}

function input(overrides: Partial<DatabaseDocInput>): DatabaseDocInput {
  return { columns: [], foreignKeys: [], indexes: [], tableSql: [], ...overrides };
}

function foreignKey(tableName: string, fromColumn: string, parentTable: string): ForeignKeyRow {
  return { tableName, fromColumn, parentTable, seq: 0 };
}

const DETAILS = (sql: string) =>
  [
    "<details>",
    "<summary>CREATE TABLE statement</summary>",
    "",
    "```sql",
    sql,
    "```",
    "",
    "</details>",
  ].join("\n");

describe("renderDatabaseDoc", () => {
  it("renders a table with no indexes, no description and no schema", () => {
    const doc = renderDatabaseDoc(
      input({
        columns: [column({ tableName: "things", name: "id", primaryKey: 1 })],
        tableSql: [tableSql("things")],
      }),
      {},
    );

    expect(doc).toBe(
      [
        HEADER,
        "",
        ["```mermaid", "erDiagram", "  things {", "    TEXT id PK", "  }", "```"].join("\n"),
        "",
        "## things",
        "",
        "### Columns",
        "",
        [
          "| Column | Type | Required | Default | Description |",
          "| ------ | ---- | -------- | ------- | ----------- |",
          "| `id`   | TEXT | yes      |         |             |",
        ].join("\n"),
        "",
        DETAILS("CREATE TABLE things (id TEXT)"),
        "",
      ].join("\n"),
    );
  });

  it("marks keys, requiredness and defaults, and keeps descriptions out of the diagram", () => {
    const schemas: TableSchemas = {
      things: z.object({
        id: z.string().meta({ description: 'The "id"\nof a thing | really' }),
        ownerId: z.string(),
        slug: z.string().nullable(),
      }),
    };
    const doc = renderDatabaseDoc(
      input({
        columns: [
          column({ tableName: "things", cid: 0, name: "id", primaryKey: 1, notNull: 0 }),
          column({ tableName: "things", cid: 1, name: "owner_id" }),
          column({ tableName: "things", cid: 2, name: "slug", notNull: 0, defaultValue: "'a|b'" }),
        ],
        foreignKeys: [foreignKey("things", "owner_id", "owners")],
        indexes: [index({ tableName: "things", name: "u", unique: 1, columns: ["slug"] })],
        tableSql: [tableSql("things")],
      }),
      schemas,
    );

    expect(doc).toContain(
      ["  things {", "    TEXT id PK", "    TEXT owner_id FK", "    TEXT slug UK", "  }"].join(
        "\n",
      ),
    );
    expect(doc).toContain(
      [
        "| Column     | Type | Required | Default  | Description                   |",
        "| ---------- | ---- | -------- | -------- | ----------------------------- |",
        '| `id`       | TEXT | yes      |          | The "id" of a thing \\| really |',
        "| `owner_id` | TEXT | yes      |          |                               |",
        "| `slug`     | TEXT | no       | `'a\\|b'` |                               |",
      ].join("\n"),
    );
  });

  it("joins the keys of one column with a comma", () => {
    const doc = renderDatabaseDoc(
      input({
        columns: [
          column({ tableName: "things", name: "id", primaryKey: 1 }),
          column({ tableName: "things", cid: 1, name: "owner_id" }),
        ],
        foreignKeys: [foreignKey("things", "id", "owners"), foreignKey("things", "owner_id", "x")],
        indexes: [
          index({ tableName: "things", name: "u", unique: 1, columns: ["owner_id"] }),
          index({ tableName: "things", name: "pk", unique: 1, origin: "pk", columns: ["id"] }),
        ],
        tableSql: [tableSql("things")],
      }),
      {},
    );

    expect(doc).toContain("    TEXT id PK, FK\n    TEXT owner_id FK, UK\n");
  });

  it.each([
    ["a non-unique index", { unique: 0 as const }],
    ["a partial unique index", { unique: 1 as const, partial: 1 as const }],
    ["a unique index over two columns", { unique: 1 as const, columns: ["a", "b"] }],
    ["a unique index over another column", { unique: 1 as const, columns: ["b"] }],
    ["a unique index on another table", { unique: 1 as const, tableName: "other" }],
  ])("does not mark UK for %s", (_name, overrides) => {
    const doc = renderDatabaseDoc(
      input({
        columns: [column({ tableName: "things", name: "a" })],
        indexes: [index({ tableName: "things", name: "i", columns: ["a"], ...overrides })],
        tableSql: [tableSql("things")],
      }),
      {},
    );

    expect(doc).toContain("    TEXT a\n");
  });

  it("draws a required foreign key as one-to-many and a nullable one as optional", () => {
    const doc = renderDatabaseDoc(
      input({
        columns: [
          column({ tableName: "b", name: "a_id" }),
          column({ tableName: "b", cid: 1, name: "c_id", notNull: 0 }),
          column({ tableName: "b", cid: 2, name: "pk_id", notNull: 0, primaryKey: 1 }),
        ],
        foreignKeys: [
          foreignKey("b", "pk_id", "p"),
          foreignKey("b", "c_id", "c"),
          foreignKey("b", "a_id", "a"),
        ],
        tableSql: [tableSql("b")],
      }),
      {},
    );

    expect(doc).toContain(
      ['  b }o--|| a : "a_id"', '  b }o--o| c : "c_id"', '  b }o--|| p : "pk_id"', "```"].join(
        "\n",
      ),
    );
  });

  it("orders relationships by table, then by column", () => {
    const doc = renderDatabaseDoc(
      input({
        columns: [
          column({ tableName: "a", name: "x" }),
          column({ tableName: "b", name: "y" }),
          column({ tableName: "b", cid: 1, name: "z" }),
        ],
        foreignKeys: [
          foreignKey("b", "z", "a"),
          foreignKey("b", "y", "a"),
          foreignKey("a", "x", "b"),
        ],
        tableSql: [tableSql("a"), tableSql("b")],
      }),
      {},
    );

    expect(doc).toContain(
      ['  a }o--|| b : "x"', '  b }o--|| a : "y"', '  b }o--|| a : "z"', "```"].join("\n"),
    );
  });

  it("throws on a foreign key from an unknown column", () => {
    expect(() =>
      renderDatabaseDoc(
        input({
          columns: [column({ tableName: "a", name: "x" })],
          foreignKeys: [foreignKey("a", "nope", "b")],
          tableSql: [tableSql("a")],
        }),
        {},
      ),
    ).toThrow("foreign key column a.nope is unknown");
  });

  it("throws on a table without a CREATE TABLE statement", () => {
    expect(() =>
      renderDatabaseDoc(input({ columns: [column({ tableName: "a", name: "x" })] }), {}),
    ).toThrow("table a has no CREATE TABLE statement");
  });

  it("renders the table description and the index table", () => {
    const schemas: TableSchemas = {
      things: z.object({}).meta({ description: "Things\nthat exist." }),
    };
    const doc = renderDatabaseDoc(
      input({
        columns: [column({ tableName: "things", name: "x" })],
        indexes: [
          index({ tableName: "things", name: "b_unique", unique: 1, columns: ["x", "y"] }),
          index({
            tableName: "things",
            name: "c_partial",
            unique: 1,
            partial: 1,
            columns: ["x"],
            sql: "CREATE UNIQUE INDEX c_partial ON things (x)\n  WHERE left_at IS NULL\n    AND x > 1",
          }),
          index({ tableName: "things", name: "a_plain", columns: ["x"] }),
          index({ tableName: "things", name: "d_pk", unique: 1, origin: "pk" }),
          index({ tableName: "things", name: "e_uc", unique: 1, origin: "u" }),
          index({ tableName: "things", name: "f_auto", partial: 1, sql: null }),
        ],
        tableSql: [tableSql("things", "CREATE TABLE things (  \n  x TEXT   \n)")],
      }),
      schemas,
    );

    expect(doc).toContain("## things\n\nThings that exist.\n\n### Columns\n");
    expect(doc).toContain(
      [
        "### Indexes",
        "",
        "| Name        | Kind              | Columns | Condition                   |",
        "| ----------- | ----------------- | ------- | --------------------------- |",
        "| `a_plain`   | index             | x       |                             |",
        "| `b_unique`  | unique index      | x, y    |                             |",
        "| `c_partial` | unique index      | x       | `left_at IS NULL AND x > 1` |",
        "| `d_pk`      | primary key       | x       |                             |",
        "| `e_uc`      | unique constraint | x       |                             |",
        "| `f_auto`    | index             | x       |                             |",
      ].join("\n"),
    );
    expect(doc).toContain(DETAILS("CREATE TABLE things (\n  x TEXT\n)"));
  });

  it("sorts tables by name and columns by position", () => {
    const doc = renderDatabaseDoc(
      input({
        columns: [
          column({ tableName: "b", cid: 1, name: "second" }),
          column({ tableName: "a", name: "only" }),
          column({ tableName: "b", cid: 0, name: "first" }),
          column({ tableName: "b", cid: 2, name: "third" }),
        ],
        tableSql: [tableSql("b"), tableSql("a")],
      }),
      {},
    );

    expect(doc.indexOf("  a {")).toBeLessThan(doc.indexOf("  b {"));
    expect(doc.indexOf("## a")).toBeLessThan(doc.indexOf("## b"));
    expect(doc).toContain("    TEXT first\n    TEXT second\n    TEXT third\n");
  });

  it("leaves only one newline at the end", () => {
    const doc = renderDatabaseDoc(
      input({
        columns: [column({ tableName: "a", name: "x" })],
        tableSql: [tableSql("a")],
      }),
      {},
    );

    expect(doc.endsWith("</details>\n")).toBe(true);
  });

  it("marks FK only on the table that owns the foreign key when two tables share a column name", () => {
    const doc = renderDatabaseDoc(
      input({
        columns: [
          column({ tableName: "a", name: "owner_id" }),
          column({ tableName: "b", name: "owner_id" }),
        ],
        foreignKeys: [foreignKey("b", "owner_id", "owners")],
        tableSql: [tableSql("a"), tableSql("b")],
      }),
      {},
    );

    expect(doc).toContain("  a {\n    TEXT owner_id\n  }\n  b {\n    TEXT owner_id FK\n  }\n");
  });

  it("reads requiredness from the column that owns the foreign key when two tables share a name", () => {
    const doc = renderDatabaseDoc(
      input({
        columns: [
          column({ tableName: "a", name: "owner_id", notNull: 0 }),
          column({ tableName: "b", name: "owner_id", notNull: 1 }),
        ],
        foreignKeys: [foreignKey("b", "owner_id", "owners"), foreignKey("a", "owner_id", "owners")],
        tableSql: [tableSql("a"), tableSql("b")],
      }),
      {},
    );

    expect(doc).toContain('  a }o--o| owners : "owner_id"\n  b }o--|| owners : "owner_id"\n');
  });

  it("trims a description that starts and ends with a newline", () => {
    const schemas: TableSchemas = {
      things: z.object({ id: z.string().meta({ description: "\nThe id.\n" }) }),
    };
    const doc = renderDatabaseDoc(
      input({
        columns: [column({ tableName: "things", name: "id" })],
        tableSql: [tableSql("things")],
      }),
      schemas,
    );

    expect(doc).toContain("| `id`   | TEXT | yes      |         | The id.     |\n");
  });

  it.each([
    [
      "a column description",
      { things: z.object({ id: z.string().meta({ description: "caf\u00e9" }) }) },
    ],
    ["a table description", { things: z.object({}).meta({ description: "caf\u00e9" }) }],
  ])("refuses %s outside printable ASCII", (_name, schemas: TableSchemas) => {
    const render = () =>
      renderDatabaseDoc(
        input({
          columns: [column({ tableName: "things", name: "id" })],
          tableSql: [tableSql("things")],
        }),
        schemas,
      );

    expect(render).toThrow(/things.* has "\u00e9", which is not printable ASCII: "caf\u00e9"/);
  });

  it("refuses a default value outside printable ASCII, naming its column", () => {
    expect(() =>
      renderDatabaseDoc(
        input({
          columns: [column({ tableName: "things", name: "note", defaultValue: "'\u2014'" })],
          tableSql: [tableSql("things")],
        }),
        {},
      ),
    ).toThrow("things.note default has");
  });

  it("accepts tabs and newlines in a description", () => {
    const schemas: TableSchemas = {
      things: z.object({ id: z.string().meta({ description: "a\tb\r\nc" }) }),
    };
    const doc = renderDatabaseDoc(
      input({
        columns: [column({ tableName: "things", name: "id" })],
        tableSql: [tableSql("things")],
      }),
      schemas,
    );

    expect(doc).toContain("| `id`   | TEXT | yes      |         | a b c       |\n");
  });
});
